sn_aia_tool.script:
/**
 * Transfer_To_Operator
 * Signals that the conversation should be escalated to a live human agent.
 * The platform's voice routing engine will pick up this output and transfer the call.
 *
 * @param {Object} inputs
 * @param {string} inputs.reason - Reason for the transfer (e.g. "fraud_detected", "customer_request")
 * @returns {Object} transfer_result
 */
(function executeScript(inputs, outputs) {
  var reason = inputs.reason || 'customer_request';

  gs.info('Banking Voice Agent - Transfer_To_Operator triggered. Reason: ' + reason);

  // Signal the transfer action for the voice channel
  outputs.transfer_action = 'live_agent';
  outputs.escalation_reason = reason;
  outputs.message = 'I want to make sure your account is completely secure. I am transferring you immediately to our fraud prevention specialists who can help you right away. Please hold.';
  outputs.success = true;
})(inputs, outputs);
